SELECT subcategory, brand, COUNT(DISTINCT variant_id) AS n_variants
FROM dim_product WHERE is_test = 0 AND is_freebie = 0 AND is_combo = 0 AND is_campaign = 0 AND is_flash_sale = 0 AND subcategory IS NOT NULL
GROUP BY subcategory, brand ORDER BY subcategory, n_variants DESC;

SELECT brand, product_title, variant_title, first_seen
FROM dim_product WHERE is_test = 0 AND is_freebie = 0 AND is_combo = 0 AND is_campaign = 0 AND is_flash_sale = 0
ORDER BY first_seen DESC LIMIT 15;
